WITH filtered AS (SELECT *, LAST_DAY(launch_date) AS launch_date_month_end FROM products WHERE launch_date > DATE '2023-08-22') SELECT *, LAG(cost) OVER w_running AS prev_cost, LEAD(price) OVER w_running AS next_price, ROW_NUMBER() OVER w_running AS row_seq, LAST_VALUE(cost) IGNORE NULLS OVER (PARTITION BY category, supplier_id ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_cost FROM filtered WINDOW w_running AS (PARTITION BY supplier_id, brand ORDER BY launch_date, id)
